scan_table_check.script:
(function (engine) {

	if (x_snc_codesanity.IsCheckApplicableToRecord())
	{
		if (x_snc_devtools.IsValidTable('sf_state_flow') == true)
		{
			var grStateFlows = new GlideRecord('sf_state_flow');
			grStateFlows.addQuery('sys_scope','=',current.sys_id);
			grStateFlows.query();
			while (grStateFlows.next())
			{
				engine.finding.increment();
			}
		}
	}

})(engine);
